L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "\230\152\168\229\164\156\227\129\175\227\131\171\227\130\175\227\131\172\227\130\183\227\130\162\227\129\140\232\168\128\227\129\163\227\129\166\227\129\143\227\130\140\227\129\166\227\128\129\230\174\191\228\184\139\227\129\140\227\129\138\231\171\139\227\129\161\227\129\171\227\129\170\227\130\139\230\188\148\229\163\135\227\130\130\232\166\139\227\129\166\227\129\141\227\129\159\227\130\147\227\129\160\227\128\130\227\129\153\227\129\148\227\129\139\227\129\163\227\129\159\227\130\136\227\128\130"
L27_1.m_Talk_ENG = "I even went to see the podium that His Highness is going to stand on yesterday. Lucrecia told me about it. It looked great."
L27_1.m_Talk_TWN = "\230\152\168\230\153\154\233\156\178\229\143\175\232\149\190\232\165\191\228\186\158\229\145\138\232\168\180\230\136\145\228\186\134\239\188\140\230\136\145\233\130\132\231\137\185\230\132\143\229\142\187\231\156\139\228\186\134\230\174\191\228\184\139\232\166\129\231\171\153\231\154\132\232\172\155\229\143\176\227\128\130\229\190\136\230\152\175\233\155\132\229\129\137\227\128\130"
L27_1.m_Talk_THA = "\224\185\128\224\184\161\224\184\183\224\185\136\224\184\173\224\184\167\224\184\178\224\184\153\224\184\156\224\184\161\224\185\132\224\184\155\224\184\148\224\184\185\224\185\129\224\184\151\224\185\136\224\184\153\224\184\158\224\184\180\224\184\152\224\184\181\224\184\151\224\184\181\224\185\136\224\184\157\224\185\136\224\184\178\224\184\154\224\184\178\224\184\151\224\184\149\224\185\137\224\184\173\224\184\135\224\184\130\224\184\182\224\185\137\224\184\153\224\185\132\224\184\155\224\184\162\224\184\183\224\184\153\224\184\161\224\184\178\224\185\129\224\184\165\224\185\137\224\184\167\224\184\148\224\185\137\224\184\167\224\184\162 \224\184\165\224\184\185\224\185\128\224\184\132\224\184\163\224\185\128\224\184\139\224\184\181\224\184\162\224\185\128\224\184\155\224\185\135\224\184\153\224\184\132\224\184\153\224\184\154\224\184\173\224\184\129 \224\184\161\224\184\177\224\184\153\224\184\170\224\184\167\224\184\162\224\184\161\224\184\178\224\184\129\224\185\128\224\184\165\224\184\162\224\184\132\224\184\163\224\184\177\224\184\154"
L27_1.m_Talk_VTN = "T\195\180i th\225\186\173m ch\195\173 \196\145\195\163 \196\145i xem b\225\187\165c ph\195\161t bi\225\187\131u m\195\160 \196\144i\225\187\135n H\225\186\161 s\225\186\189 \196\145\225\187\169ng v\195\160o ng\195\160y mai. Lucrecia \196\145\195\163 k\225\187\131 cho t\195\180i. N\195\179 tr\195\180ng r\225\186\165t tuy\225\187\135t."
L27_1.m_Talk_SCN = "\230\152\168\230\153\154\229\141\162\229\133\139\233\155\183\232\165\191\228\186\154\229\145\138\232\175\137\230\136\145\228\186\134\239\188\140\230\136\145\232\191\152\231\137\185\230\132\143\229\142\187\231\156\139\228\186\134\230\174\191\228\184\139\232\166\129\231\171\153\231\154\132\232\174\178\229\143\176\227\128\130\229\190\136\230\152\175\233\155\132\228\188\159\227\128\130"
L27_1.m_Talk_DEU = "Ich habe mir gestern Nacht sogar das Podium angesehen, auf dem Seine Hoheit stehen wird. Lucrecia hat mir davon erz\195\164hlt. Es sah gro\195\159artig aus."
